package com.flairs.libraryapi.model;

import jakarta.persistence.Entity;
import jakarta.persistence.Table;
import java.time.Instant;
import java.time.LocalDate;

// TODO 2: map this class to the "loans" table you created in V4.
//  - id: primary key generated by the database (IDENTITY)
//  - book and member: many-to-one, LAZY, not optional, with the right @JoinColumn names
//  - borrowedAt, dueDate, returnedAt: @Column with the snake_case names from V4
// The app will NOT start until this mapping matches the table (ddl-auto: validate).
@Entity
@Table(name = "loans")
public class Loan {

    private Long id;

    private Book book;

    private Member member;

    private Instant borrowedAt = Instant.now();

    private LocalDate dueDate;

    private Instant returnedAt;

    protected Loan() {
    }

    public Loan(Book book, Member member, LocalDate dueDate) {
        this.book = book;
        this.member = member;
        this.dueDate = dueDate;
    }

    public boolean isActive() {
        return returnedAt == null;
    }

    public void markReturned() {
        this.returnedAt = Instant.now();
    }

    public Long getId() {
        return id;
    }

    public Book getBook() {
        return book;
    }

    public Member getMember() {
        return member;
    }

    public Instant getBorrowedAt() {
        return borrowedAt;
    }

    public LocalDate getDueDate() {
        return dueDate;
    }

    public Instant getReturnedAt() {
        return returnedAt;
    }
}
